<script setup>
import {computed,reactive,ref,watch} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {effectiveDeviceConnection} from '../../data/queries.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import MetricCard from '../../components/MetricCard.vue'
import ResourceForm from '../fields/ResourceForm.vue'
import {kindNames,shortStamp,sortRows,options} from '../fields/resourceUi.js'
const r=useIrrigation(),router=useRouter(),route=useRoute(),clock=useClock(),ui=useListState('devices',{filters:{code:'',kind:'',connection:'',verification:''}}),search=reactive({...ui.filters}),registering=ref(false)
const devices=computed(()=>(r.state.entities.Device??[]).map(d=>({...d,connection:effectiveDeviceConnection(d,clock.displayNow.value)}))),kinds=computed(()=>[...new Set(devices.value.map(d=>d.kind))]),filtered=computed(()=>sortRows(devices.value.filter(d=>d.code.toLowerCase().includes(ui.filters.code.trim().toLowerCase())&&(!ui.filters.kind||d.kind===ui.filters.kind)&&(!ui.filters.connection||d.connection===ui.filters.connection)&&(!ui.filters.verification||d.verification===ui.filters.verification)),ui.sort)),rows=computed(()=>filtered.value.slice((ui.page-1)*15,ui.page*15))
const count=key=>filtered.value.filter(d=>d.connection===key||d.verification===key).length
function query(){ui.filters={...search};ui.page=1}
watch(()=>route.query.connection,value=>{if(['OFFLINE','ONLINE','UNKNOWN'].includes(value)){search.connection=value;query()}},{immediate:true})
function metric(key,value){search[key]=value;query()}
function view(d){ui.selectedId=d.deviceId;router.push('/devices/'+d.deviceId)}
const registration={code:'',name:'',kind:'',manufacturer:'',model:'',gatewayDeviceId:'',protocol:'',endpoint:''}
const fields=computed(()=>[{key:'code',label:'设备编号',required:true},{key:'name',label:'设备名称',required:true},{key:'kind',label:'设备类型',options:kinds.value.map(value=>({value,label:kindNames[value]??value}))},{key:'manufacturer',label:'生产厂家',required:true},{key:'model',label:'设备型号',required:true},{key:'gatewayDeviceId',label:'所属网关',options:options(devices.value.filter(d=>d.kind==='GATEWAY'),'deviceId')},{key:'protocol',label:'接入方式',required:true},{key:'endpoint',label:'接入端点',required:true}])
const columns=[{key:'index',label:'序号',width:70},{key:'code',label:'设备编号',sortable:true},{key:'name',label:'设备名称',sortable:true},{key:'kind',label:'类型'},{key:'connection',label:'连接'},{key:'verification',label:'核验'},{key:'lastSeenAt',label:'最后心跳',sortable:true},{key:'actions',label:'操作'}]
</script>
<template><div class="page-stack devices-screen"><form class="filters" @submit.prevent="query"><label class="filter-field device-code">设备编号<input v-model="search.code" placeholder="请输入设备编号"/></label><label class="filter-field">设备类型<select v-model="search.kind"><option value="">全部</option><option v-for="kind in kinds" :key="kind" :value="kind">{{kindNames[kind]??kind}}</option></select></label><label class="filter-field">连接状态<select v-model="search.connection"><option value="">全部</option><option value="ONLINE">在线</option><option value="OFFLINE">离线</option><option value="UNKNOWN">未知</option></select></label><button class="btn btn-primary">查询</button><button class="btn" type="button" :disabled="!r.can('DEVICE_CREATE')" @click="registering=true">登记设备</button></form><div class="stat-grid"><MetricCard label="设备总数" :value="filtered.length" icon="device" tabindex="0" role="button" @click="metric('connection','');metric('verification','')" @keydown.enter="metric('connection','');metric('verification','')"/><MetricCard label="在线设备" :value="count('ONLINE')" icon="wifi" tabindex="0" role="button" @click="metric('connection','ONLINE')" @keydown.enter="metric('connection','ONLINE')"/><MetricCard label="离线设备" :value="count('OFFLINE')" icon="wifi" tone="danger" tabindex="0" role="button" @click="metric('connection','OFFLINE')" @keydown.enter="metric('connection','OFFLINE')"/><MetricCard label="已核验" :value="count('VERIFIED')" icon="check" tabindex="0" role="button" @click="metric('verification','VERIFIED')" @keydown.enter="metric('verification','VERIFIED')"/></div><section class="panel device-table"><DataTable :columns="columns" :rows="rows" row-key="deviceId" :selected-id="ui.selectedId" v-model:sort="ui.sort" @row-click="view"><template #cell-index="{index}">{{(ui.page-1)*15+index+1}}</template><template #cell-code="{row}"><button class="btn-plain" @click.stop="view(row)">{{row.code}}</button></template><template #cell-kind="{value}">{{kindNames[value]??value}}</template><template #cell-connection="{value}"><StatusBadge :status="value"/></template><template #cell-verification="{value}"><StatusBadge :status="value"/></template><template #cell-lastSeenAt="{value}">{{shortStamp(value)}}</template><template #cell-actions="{row}"><button class="btn-link" @click.stop="view(row)">查看</button></template></DataTable><Pagination v-model="ui.page" :total="filtered.length" show-total-pages/></section><ResourceForm v-if="registering" title="登记设备" action="DEVICE_CREATE" :record="registration" :fields="fields" @close="registering=false"/></div></template>
<style scoped>.devices-screen{gap:17px}.devices-screen .filters{gap:20px;padding:4px 4px 5px}.device-code{flex:1.4}.devices-screen .filters .btn{min-width:151px}.devices-screen :deep(.metric-card){height:104px;cursor:pointer}.device-table{padding:15px 17px 23px}.device-table :deep(.data-table td){height:35.7px}.device-table :deep(.pagination){margin-top:22px}.device-table :deep(.status-badge){line-height:1.5}
</style>
